#!/usr/bin/env python3
import gzip
import sys
from collections import defaultdict


def open_text(path):
    with open(path, "rb") as probe:
        is_gzip = probe.read(2) == b"\x1f\x8b"
    return gzip.open(path, "rt") if is_gzip else open(path, "rt")


def read_fasta(path):
    records = []
    name = None
    chunks = []
    with open_text(path) as handle:
        for line in handle:
            line = line.strip()
            if not line:
                continue
            if line.startswith(">"):
                if name is not None:
                    records.append((name, "".join(chunks).upper()))
                name = line[1:].split()[0]
                chunks = []
            else:
                chunks.append(line)
    if name is not None:
        records.append((name, "".join(chunks).upper()))
    return records


def reads_fastq(path):
    with open_text(path) as handle:
        while True:
            header = handle.readline()
            if not header:
                return
            sequence = handle.readline().strip().upper()
            handle.readline()
            handle.readline()
            if sequence:
                yield sequence


def reverse_complement(sequence):
    return sequence.translate(str.maketrans("ACGTN", "TGCAN"))[::-1]


def make_index(sequence, k):
    index = defaultdict(list)
    for position in range(len(sequence) - k + 1):
        index[sequence[position : position + k]].append(position)
    return index


def mismatch_count(read, reference, start):
    window = reference[start : start + len(read)]
    return sum(a != b for a, b in zip(read, window))


def best_for_contig(read, sequence, indexes, k):
    if len(read) > len(sequence):
        return None
    candidates = set()
    orientations = (read, reverse_complement(read))
    offsets = range(0, len(read) - k + 1, max(1, k // 2))
    for oriented in orientations:
        for offset in offsets:
            seed = oriented[offset : offset + k]
            for position in indexes.get(seed, ()):
                start = position - offset
                if 0 <= start <= len(sequence) - len(read):
                    candidates.add((start, oriented))
    if not candidates:
        return None
    return min(mismatch_count(oriented, sequence, start) for start, oriented in candidates)


def classify(read, references, indexes_by_k):
    scores = []
    for name, sequence in references:
        score = best_for_contig(read, sequence, indexes_by_k[name][12], 12)
        scores.append(score)
    for i, (name, sequence) in enumerate(references):
        if scores[i] is None:
            scores[i] = best_for_contig(read, sequence, indexes_by_k[name][8], 8)
    available = [(score, i) for i, score in enumerate(scores) if score is not None]
    if not available:
        return "unassigned", None
    available.sort()
    if len(available) > 1 and available[0][0] == available[1][0]:
        return "ambiguous", available[0][0]
    return references[available[0][1]][0], available[0][0]


def main(reference_path, reads_path, output_path):
    references = read_fasta(reference_path)
    indexes_by_k = {
        name: {12: make_index(sequence, 12), 8: make_index(sequence, 8)}
        for name, sequence in references
    }
    counts = {name: 0 for name, _ in references}
    mismatch_sums = {name: 0 for name, _ in references}
    total = assigned = ambiguous = unassigned = 0
    for read in reads_fastq(reads_path):
        total += 1
        label, score = classify(read, references, indexes_by_k)
        if label == "ambiguous":
            ambiguous += 1
        elif label == "unassigned":
            unassigned += 1
        else:
            assigned += 1
            counts[label] += 1
            mismatch_sums[label] += score
    with open(output_path, "w") as out:
        out.write("metric\tvalue\n")
        out.write(f"total_reads\t{total}\n")
        out.write(f"assigned_reads\t{assigned}\n")
        out.write(f"ambiguous_reads\t{ambiguous}\n")
        out.write(f"unassigned_reads\t{unassigned}\n")
        out.write("contig\tcount\tpercent_assigned\tmean_mismatches\n")
        for name, _ in references:
            count = counts[name]
            percent = (100.0 * count / assigned) if assigned else 0.0
            mean_mismatches = (mismatch_sums[name] / count) if count else 0.0
            out.write(f"{name}\t{count}\t{percent:.6f}\t{mean_mismatches:.6f}\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2], sys.argv[3])

