#!/usr/bin/env python3
import gzip
import sys
from collections import defaultdict


def open_text(path):
    with open(path, "rb") as probe:
        is_gzip = probe.read(2) == b"\x1f\x8b"
    return gzip.open(path, "rt") if is_gzip else open(path, "rt")


def read_fasta(path):
    records = []
    name = None
    chunks = []
    with open_text(path) as handle:
        for line in handle:
            line = line.strip()
            if not line:
                continue
            if line.startswith(">"):
                if name is not None:
                    records.append((name, "".join(chunks).upper()))
                name = line[1:].split()[0]
                chunks = []
            else:
                chunks.append(line)
    if name is not None:
        records.append((name, "".join(chunks).upper()))
    return records


def reads_fastq(path):
    with open_text(path) as handle:
        while True:
            header = handle.readline()
            if not header:
                return
            sequence = handle.readline().strip().upper()
            handle.readline()
            handle.readline()
            if sequence:
                yield sequence


def reverse_complement(sequence):
    return sequence.translate(str.maketrans("ACGTN", "TGCAN"))[::-1]


def make_index(sequence, k):
    index = defaultdict(list)
    for position in range(len(sequence) - k + 1):
        index[sequence[position : position + k]].append(position)
    return index


def mismatch_count(read, reference, start):
    window = reference[start : start + len(read)]
    return sum(a != b for a, b in zip(read, window))


def best_for_contig(read, sequence, indexes, k):
    if len(read) > len(sequence):
        return None
    candidates = set()
    orientations = (read, reverse_complement(read))
    offsets = range(0, len(read) - k + 1, max(1, k // 2))
    for oriented in orientations:
        for offset in offsets:
            seed = oriented[offset : offset + k]
            for position in indexes.get(seed, ()):
                start = position - offset
                if 0 <= start <= len(sequence) - len(read):
                    candidates.add((start, oriented))
    if not candidates:
        return None
    return min(mismatch_count(oriented, sequence, start) for start, oriented in candidates)


def brute_best_for_contig(read, sequence):
    if len(read) > len(sequence):
        return None
    orientations = (read, reverse_complement(read))
    return min(
        mismatch_count(oriented, sequence, start)
        for oriented in orientations
        for start in range(len(sequence) - len(read) + 1)
    )


def classify(read, references, indexes_by_k):
    scores = []
    for name, sequence in references:
        score = best_for_contig(read, sequence, indexes_by_k[name][12], 12)
        scores.append(score)
    for i, (name, sequence) in enumerate(references):
        if scores[i] is None:
            scores[i] = best_for_contig(read, sequence, indexes_by_k[name][8], 8)
    available = [(score, i) for i, score in enumerate(scores) if score is not None]
    if not available:
        return "unassigned", None, scores
    available.sort()
    if len(available) > 1 and available[0][0] == available[1][0]:
        return "ambiguous", available[0][0], scores
    return references[available[0][1]][0], available[0][0], scores


def main(reference_path, reads_path, output_path):
    references = read_fasta(reference_path)
    indexes_by_k = {
        name: {12: make_index(sequence, 12), 8: make_index(sequence, 8)}
        for name, sequence in references
    }
    counts = {name: 0 for name, _ in references}
    mismatch_sums = {name: 0 for name, _ in references}
    total = assigned = ambiguous = unassigned = 0
    debug_rows = []
    for read in reads_fastq(reads_path):
        total += 1
        label, score, scores = classify(read, references, indexes_by_k)
        if len(debug_rows) < 20:
            seeded = ",".join("-" if value is None else str(value) for value in scores)
            brute = ",".join(str(brute_best_for_contig(read, sequence)) for _, sequence in references)
            debug_rows.append((total, len(read), label, seeded, brute))
        if label == "ambiguous":
            ambiguous += 1
        elif label == "unassigned":
            unassigned += 1
        else:
            assigned += 1
            counts[label] += 1
            mismatch_sums[label] += score
    with open(output_path, "w") as out:
        out.write("metric\tvalue\n")
        out.write(f"total_reads\t{total}\n")
        out.write(f"assigned_reads\t{assigned}\n")
        out.write(f"ambiguous_reads\t{ambiguous}\n")
        out.write(f"unassigned_reads\t{unassigned}\n")
        out.write("contig\tcount\tpercent_assigned\tmean_mismatches\n")
        for name, _ in references:
            count = counts[name]
            percent = (100.0 * count / assigned) if assigned else 0.0
            mean_mismatches = (mismatch_sums[name] / count) if count else 0.0
            out.write(f"{name}\t{count}\t{percent:.6f}\t{mean_mismatches:.6f}\n")
        out.write("debug_read\tlength\tclassification\tseeded_scores\tbrute_scores\n")
        for row in debug_rows:
            out.write("\t".join(map(str, row)) + "\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2], sys.argv[3])

#!/usr/bin/env python3
import gzip
import math
import sys
from collections import defaultdict


def open_text(path):
    with open(path, "rb") as probe:
        is_gzip = probe.read(2) == b"\x1f\x8b"
    return gzip.open(path, "rt") if is_gzip else open(path, "rt")


def read_fasta(path):
    records = []
    name = None
    chunks = []
    with open_text(path) as handle:
        for line in handle:
            line = line.strip()
            if not line:
                continue
            if line.startswith(">"):
                if name is not None:
                    records.append((name, "".join(chunks).upper()))
                name = line[1:].split()[0]
                chunks = []
            else:
                chunks.append(line)
    if name is not None:
        records.append((name, "".join(chunks).upper()))
    return records


def reads_fastq(path):
    with open_text(path) as handle:
        while True:
            header = handle.readline()
            if not header:
                return
            sequence = handle.readline().strip().upper()
            handle.readline()
            handle.readline()
            if sequence:
                yield sequence


def reverse_complement(sequence):
    return sequence.translate(str.maketrans("ACGTN", "TGCAN"))[::-1]


def make_index(sequence, k):
    index = defaultdict(list)
    for position in range(len(sequence) - k + 1):
        index[sequence[position : position + k]].append(position)
    return index


def mismatch_count(read, reference, start):
    window = reference[start : start + len(read)]
    return sum(a != b for a, b in zip(read, window))


def candidate_distances(read, sequence, index, k):
    """Return Hamming distances for every seed-supported alignment window."""
    if len(read) > len(sequence):
        return []
    candidates = set()
    orientations = (read, reverse_complement(read))
    # Use every seed offset so an error in one seed does not hide the true
    # window.  The k=8 seed is short enough to remain present for small error.
    for oriented in orientations:
        for offset in range(len(read) - k + 1):
            seed = oriented[offset : offset + k]
            for position in index.get(seed, ()):
                start = position - offset
                if 0 <= start <= len(sequence) - len(read):
                    candidates.add((start, oriented))
    return [mismatch_count(oriented, sequence, start) for start, oriented in candidates]


def brute_distances(read, sequence):
    if len(read) > len(sequence):
        return []
    orientations = (read, reverse_complement(read))
    return [
        mismatch_count(oriented, sequence, start)
        for oriented in orientations
        for start in range(len(sequence) - len(read) + 1)
    ]


def logsumexp(values):
    largest = max(values)
    return largest + math.log(sum(math.exp(value - largest) for value in values))


def read_distance_histograms(read, references, indexes):
    """Collect Hamming-distance histograms for seed-supported windows."""
    histograms = []
    no_seed = 0
    for name, sequence in references:
        distances = candidate_distances(read, sequence, indexes[name], 8)
        if not distances:
            # This is rare at the supplied small error rate.  Brute force is
            # retained as an exact fallback for reads with no exact 8-mer.
            distances = brute_distances(read, sequence)
            no_seed += 1
        histogram = defaultdict(int)
        for distance in distances:
            histogram[distance] += 1
        histograms.append(dict(histogram))
    return histograms, no_seed


def histogram_log_likelihood(histogram, penalty):
    if not histogram:
        return -float("inf")
    return logsumexp(
        math.log(count) - penalty * distance
        for distance, count in histogram.items()
    )


def em(log_likelihood_rows, chromosome_count):
    proportions = [1.0 / chromosome_count] * chromosome_count
    for iteration in range(500):
        updated = [0.0] * chromosome_count
        for log_likelihoods in log_likelihood_rows:
            terms = [
                math.log(proportions[index]) + log_likelihoods[index]
                if proportions[index] > 0 and math.isfinite(log_likelihoods[index])
                else -float("inf")
                for index in range(chromosome_count)
            ]
            largest = max(terms)
            weights = [math.exp(term - largest) for term in terms]
            denominator = sum(weights)
            for index in range(chromosome_count):
                updated[index] += weights[index] / denominator
        updated = [value / len(log_likelihood_rows) for value in updated]
        if max(abs(updated[index] - proportions[index]) for index in range(chromosome_count)) < 1e-11:
            proportions = updated
            break
        proportions = updated
    return proportions, iteration + 1


def main(reference_path, reads_path, output_path):
    references = read_fasta(reference_path)
    indexes = {
        name: make_index(sequence, 8) for name, sequence in references
    }
    reads = list(reads_fastq(reads_path))
    error_rates = (0.005, 0.008, 0.01, 0.02, 0.05)
    histogram_rows = []
    total_no_seed = 0
    reads_with_no_seed = 0
    informative = 0
    score_range_sum = 0
    for read in reads:
        # The distance histograms are independent of the assumed error rate.
        histograms, no_seed = read_distance_histograms(read, references, indexes)
        histogram_rows.append(histograms)
        total_no_seed += no_seed
        if no_seed:
            reads_with_no_seed += 1
        minima = [min(histogram) for histogram in histograms if histogram]
        if minima:
            score_range_sum += max(minima) - min(minima)
            if max(minima) > min(minima):
                informative += 1

    with open(output_path, "w") as out:
        out.write("metric\tvalue\n")
        out.write(f"total_reads\t{len(reads)}\n")
        out.write(f"informative_reads\t{informative}\n")
        out.write(f"reads_with_no_seed_for_any_contig\t{reads_with_no_seed}\n")
        out.write(f"contig_no_seed_events\t{total_no_seed}\n")
        out.write(f"mean_log_score_range\t{score_range_sum / len(histogram_rows):.6f}\n")
        out.write("error_rate\tchr1\tchr2\tchr3\tchr4\titerations\n")
        for error_rate in error_rates:
            penalty = math.log(3.0 * (1.0 - error_rate) / error_rate)
            scaled_rows = []
            for histograms in histogram_rows:
                scaled_rows.append([
                    histogram_log_likelihood(histogram, penalty)
                    for histogram in histograms
                ])
            proportions, iterations = em(scaled_rows, len(references))
            values = [100.0 * proportion for proportion in proportions]
            out.write(
                f"{error_rate:.3f}\t" + "\t".join(f"{value:.6f}" for value in values)
                + f"\t{iterations}\n"
            )


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2], sys.argv[3])

